mapper.select:
SELECT m.id, m.author_id, m.group_id, m.sort, m.create_time, a.nickname AS author_nickname, a.avatar_url AS author_avatar_url FROM author_group_item m LEFT JOIN author_user a ON a.id = m.author_id WHERE m.deleted = 0
AND m.group_id = #{reqVO.groupId}
AND m.author_id = #{reqVO.authorId}
ORDER BY m.sort ASC, m.id DESC
